WITH valid AS (SELECT id, customer_id, store_id, order_date, channel, amount, discount, shipping_fee, CASE WHEN status IN ('SHIPPED', 'RETURNED') THEN 'Priority' ELSE 'Other' END status_group, amount / NULLIF(discount, 0) amount_per_discount FROM orders WHERE order_date > TO_DATE('2023-11-20') AND channel IS NOT NULL AND channel IN ('web', 'partner')) SELECT id, customer_id, store_id, order_date, channel, amount, discount, shipping_fee, status_group, amount_per_discount, STDDEV_SAMP(shipping_fee) OVER (PARTITION BY channel) channel_stddev_samp_shipping_fee, FIRST_VALUE(shipping_fee, TRUE) OVER w_running first_known_shipping_fee FROM valid WINDOW w_running AS (ORDER BY amount, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW);
